const range = "e3c1782b96~10";
const end = "e3c1782b96";
const filesResult = await tools["run_shell_command"]({command: `git diff --name-only --diff-filter=ACMR ${range} ${end} -- '*.ts' '*.tsx' '*.mts' '*.cts'`, dir_path: "/Volumes/XS1000/acoliver/projects/llxprt/branch-5/llxprt-code", description: "List changed TypeScript files in the requested commit range"});
if (!filesResult.ok) throw new Error(filesResult.error.message);
if (filesResult.value.exitCode !== 0) throw new Error(filesResult.value.stderr || filesResult.value.stdout);
const files = filesResult.value.stdout.trim().split("\n").filter(Boolean);
const quote = s => "'" + s.replaceAll("'", "'\\''") + "'";
const entries = [];
for (const file of files) {
  const show = await tools["run_shell_command"]({command: `git show ${end}:${quote(file)}`, dir_path: "/Volumes/XS1000/acoliver/projects/llxprt/branch-5/llxprt-code", description: "Read changed TypeScript file at endpoint commit"});
  if (!show.ok) throw new Error(show.error.message);
  if (show.value.exitCode !== 0) continue;
  const lines = show.value.stdout.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!line.includes("@plan")) continue;
    const matches = [...line.matchAll(/@plan\s*(?:[:(]\s*)?([A-Za-z0-9_.-]+)/g)];
    if (!matches.length) {
      entries.push({file, line: i + 1, text: line.trim(), plan: "(no ID parsed)"});
      continue;
    }
    for (const match of matches) entries.push({file, line: i + 1, text: line.trim(), plan: match[1]});
  }
}
for (const entry of entries) {
  const blame = await tools["run_shell_command"]({command: `git blame --line-porcelain -L ${entry.line},${entry.line} ${end} -- ${quote(entry.file)}`, dir_path: "/Volumes/XS1000/acoliver/projects/llxprt/branch-5/llxprt-code", description: "Attribute marker line with git blame"});
  if (!blame.ok) throw new Error(blame.error.message);
  if (blame.value.exitCode !== 0) throw new Error(blame.value.stderr || blame.value.stdout);
  const hash = blame.value.stdout.match(/^([0-9a-f]{40}) /)?.[1];
  entry.commit = hash ? hash.slice(0, 7) : "(unknown)";
}
const count = items => { const out = {}; for (const x of items) out[x] = (out[x] || 0) + 1; return Object.fromEntries(Object.entries(out).sort(([a], [b]) => a.localeCompare(b))); };
const packageName = file => { const m = file.match(/^packages\/([^/]+)/); return m ? `packages/${m[1]}` : "(outside packages)"; };
return {range: `${range}..${end}`, changedTypeScriptFiles: files.length, totalMarkers: entries.length, byPlan: count(entries.map(x => x.plan)), byPackage: count(entries.map(x => packageName(x.file))), byLastTouchedCommit: count(entries.map(x => x.commit)), markers: entries};

